private TreeNode<T> rotateRight(TreeNode<T> node) {
    // edge case: if the node is null or it has no right child, return the same node
    if (node == null || node.getRightChild() == null) {
        return node;
    }

    // get the right child of the node
    TreeNode<T> rightChild = node.getRightChild();

    // move the right child's left child to be the right child of the node
    node.setRightChild(rightChild.getLeftChild());

    // make the right child the new parent of the node
    node = rightChild;

    // move the node's left child to be the right child of the new parent
    node.getRightChild().setLeftChild(node);

    return node;
}

public TreeNode<T> rotateRight(TreeNode<T> node) {
    // Check if the node is null
    if (node == null) {
        throw new NullPointerException("Cannot rotate a null node");
    }

    // Get the right child of the node
    TreeNode<T> rightChild = node.getRightChild();

    // Check if the right child is null
    if (rightChild == null) {
        throw new NullPointerException("Cannot rotate a node with a null right child");
    }

    // Get the left child of the right child
    TreeNode<T> leftChild = rightChild.getLeftChild();

    // Check if the left child is null
    if (leftChild == null) {
        throw new NullPointerException("Cannot rotate a node with a null left child");
    }

    // Update the links between the nodes
    node.setRightChild(leftChild);
    rightChild.setLeftChild(node);

    // Return the new parent of the node
    return rightChild;
}

public TreeNode<T> rotateRight(TreeNode<T> node) {
    // Check if node is null
    if (node == null) {
        throw new IllegalArgumentException("Node cannot be null");
    }

    // Check if node has a right child
    if (node.right == null) {
        throw new IllegalArgumentException("Node must have a right child");
    }

    // Find the node's right child
    TreeNode<T> newParent = node.right;

    // Find the right child's left child
    TreeNode<T> leftChild = newParent.left;

    // Set the new parent's left child to the node
    newParent.left = node;

    // Set the node's right child to the left child of the new parent
    node.right = leftChild;

    // Return the new parent
    return newParent;
}

