public void write(byte[] b) throws IOException {
    // Check if the input array is null or has a length of 0
    if (b == null || b.length == 0) {
        // If the input array is null or has a length of 0, do nothing
        return;
    }

    // Calculate the number of bytes to write
    int numBytes = Math.min(b.length, this.buffer.length - this.bufferIndex);

    // Copy the bytes from the input array to the output buffer
    System.arraycopy(b, 0, this.buffer, this.bufferIndex, numBytes);

    // Increment the buffer index by the number of bytes written
    this.bufferIndex += numBytes;

    // Check if the buffer is full
    if (this.bufferIndex == this.buffer.length) {
        // If the buffer is full, flush it
        flushBuffer();
    }
}

