    if (graph == null) {
        throw new IllegalArgumentException("Input graph cannot be null");
    }

    // Create a new mapping with the same vertices as the input graph
    IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<>(graph.getVertices());

    // Iterate over the vertices of the input graph and map each vertex to itself
    for (V vertex : graph.getVertices()) {
        mapping.setIdentity(vertex, vertex);
    }

    return mapping;
}

