    }

    // Insert the bucket before the previous bucket
    if (previousBucket != null) {
        previousBucket.getNextBuckets().add(bucket);
        bucket.getPriorBuckets().add(previousBucket);
    }

    // Insert the bucket into the data structure
    addToBuckets(bucket);
}

public void insertBefore(Bucket bucket) {
     // Check if the bucket parameter is null
     if (bucket == null) {
         throw new IllegalArgumentException("Cannot insert a null bucket");
     }

     // Check if this bucket is already in the data structure
     if (this.getDataStructure().contains(this)) {
         throw new IllegalStateException("This bucket is already in the data structure");
     }

     // Insert this bucket before the specified bucket in the data structure
     List<Bucket> dataStructure = this.getDataStructure();
     int index = dataStructure.indexOf(bucket);
     if (index == -1) {
         throw new IllegalArgumentException("The specified bucket is not in the data structure");
     }
     dataStructure.add(index, this);
 }

