public Mappings diffStructure(String tableName, Mappings mappings) {
    // Initialize the output Mappings
    Mappings outputMappings = new Mappings();

    // Get the source and destination fields
    Set<String> srcFields = mappings.get(tableName).keySet();
    Set<String> dstFields = outputMappings.get(tableName).keySet();

    // Iterate over the source fields and add the missing fields to the output Mappings
    for(String srcField : srcFields) {
        if(!dstFields.contains(srcField)) {
            outputMappings.get(tableName).put(srcField, mappings.get(tableName).get(srcField));
        }
    }

    return outputMappings;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Define the list of fields that should not be included in the output
    List<String> ignoredFields = Arrays.asList("_source");

    // Create a new mappings object to hold the differences
    Mappings diffMappings = new Mappings();

    // Iterate over the fields in the input mappings
    for (Map.Entry<String, Object> entry : mappings.entrySet()) {
        String fieldName = entry.getKey();
        Object fieldValue = entry.getValue();

        // Check if the field should be ignored
        if (ignoredFields.contains(fieldName)) {
            // Skip to the next field
            continue;
        }

        // Add the field to the diff mappings if it is not already present
        if (!diffMappings.containsKey(fieldName)) {
            diffMappings.put(fieldName, fieldValue);
        }
    }

    return diffMappings;
}

public Mappings diffStructure(String tableName, Mappings mappings) {

    // Define the output mappings
    Mappings diffMappings = new Mappings();
    diffMappings.set("_meta", mappings.get("_meta"));
    diffMappings.set("_parent", mappings.get("_parent"));

    // Get the existing fields in the mappings
    Map<String, Object> existingFields = mappings.get("properties");

    // Iterate through the properties and check if they exist in the input mappings
    for (Map.Entry<String, Object> entry : existingFields.entrySet()) {
      Object value = entry.getValue();
      if (value instanceof Map) {
        Map<String, Object> mapValue = (Map<String, Object>) value;
        // Check if the field exists in the input mappings
        if (!mapValue.containsKey("type")) {
          diffMappings.put("properties", entry.getKey(), value);
        }
      }
    }

    return diffMappings;
  }

public Mappings diffStructure(String tableName, Mappings mappings) {
    if (mappings == null) {
        return Mappings.fromPairs(tableName, Collections.emptyList());
    }

    Set<String> existingFields = mappings.getFields().stream()
            .map(field -> field.getName().toUpperCase(Locale.ROOT))
            .collect(Collectors.toSet());

    List<Mappings.Field> notExistingFields = new ArrayList<>();
    List<Mappings.Field> newFields = new ArrayList<>();
    List<Mappings.Field> existingFieldsToRemove = new ArrayList<>();
    List<Mappings.Field> existingFieldsToUpdate = new ArrayList<>();

    for (Mappings.Field field : mappings.getFields()) {
        if (existingFields.contains(field.getName().toUpperCase(Locale.ROOT))) {
            existingFields.remove(field.getName().toUpperCase(Locale.ROOT));
            existingFieldsToUpdate.add(field);
        } else {
            newFields.add(field);
        }
    }

    for (String existingField : existingFields) {
        notExistingFields.add(new Mappings.Field(tableName, existingField.toLowerCase(Locale.ROOT), Mappings.Type.TEXT, Collections.emptyList()));
    }

    return Mappings.builder()
            .addFields(newFields)
            .addFields(existingFieldsToRemove)
            .addFields(existingFieldsToUpdate)
            .addNotAnalyzerFields(notExistingFields)
            .build();
}

Mappings diffStructure(String tableName, Mappings mappings) {
    // Step 1: Check if the input mappings are null or empty
    if (mappings == null || mappings.isEmpty()) {
        throw new IllegalArgumentException("Mappings cannot be null or empty");
    }

    // Step 2: Check if the table name is valid
    if (tableName == null || tableName.isEmpty()) {
        throw new IllegalArgumentException("Table name cannot be null or empty");
    }

    // Step 3: Create a new Mappings object with the history mapping
    Mappings diffMappings = new Mappings();
    diffMappings.index(tableName);

    // Step 4: Loop through each field in the input mappings
    for (String fieldName : mappings.fields()) {
        // Step 5: Check if the field exists in the diffMappings
        if (!diffMappings.hasField(fieldName)) {
            // Step 6: Add the field to the diffMappings
            diffMappings.field(fieldName, mappings.field(fieldName));
        }
    }

    // Step 7: Return the diffMappings
    return diffMappings;
}

