public long readLong(int offset) {
    // Validate the offset
    if (offset < 0 || offset + 2 > getBytes().length) {
        throw new IndexOutOfBoundsException("Invalid offset: " + offset + ", class size: " + getBytes().length);
    }

    // Read the value
    long value = (getBytes()[offset] & 0xFFL) << 56;
    value |= (getBytes()[offset + 1] & 0xFFL) << 48;
    value |= (getBytes()[offset + 2] & 0xFFL) << 40;
    value |= (getBytes()[offset + 3] & 0xFFL) << 32;
    value |= (getBytes()[offset + 4] & 0xFFL) << 24;
    value |= (getBytes()[offset + 5] & 0xFFL) << 16;
    value |= (getBytes()[offset + 6] & 0xFFL) << 8;
    value |= (getBytes()[offset + 7] & 0xFFL);

    return value;
}

