protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Edge case: If the start and end time are already smaller than the fetch data duration, return a list with a single time range
    if (start < FETCH_DATA_DURATION && end < FETCH_DATA_DURATION) {
        return Collections.singletonList(new TimeRange(start, end));
    }

    List<TimeRange> timeRanges = new ArrayList<>();

    long currentStart = start;
    long currentEnd = start;

    while (currentEnd < end) {
        // If the current end time plus the fetch data duration is greater than the end time, set the current end time to the end time
        if (currentEnd + FETCH_DATA_DURATION > end) {
            currentEnd = end;
        } else {
            currentEnd += FETCH_DATA_DURATION;
        }

        timeRanges.add(new TimeRange(currentStart, currentEnd));

        // Set the current start time to the current end time
        currentStart = currentEnd;
    }

    return timeRanges;
}

public static List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();

        // Check input validity
        if (start <= end && start >= 0 && end >= 0) {
            long startTime = start;
            long endTime = end;

            // Split the time range into multiple ranges
            while (startTime < endTime) {
                // Determine the duration for the current range
                long duration = Math.min(endTime - startTime, FETCH_DATA_DURATION);

                // Add the current range to the list
                timeRanges.add(new TimeRange(startTime, startTime + duration));

                // Update the start time for the next range
                startTime += duration;
            }
        } else {
            throw new IllegalArgumentException("Invalid input: start must be less than or equal to end and both must be non-negative");
        }

        return timeRanges;
    }

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = FETCH_DATA_DURATION;

    // Handle invalid input
    if (start < 0) {
        throw new IllegalArgumentException("Start time must be non-negative");
    }
    if (end < 0) {
        throw new IllegalArgumentException("End time must be non-negative");
    }

    // Handle edge cases
    if (start == end || start > end) {
        return Collections.emptyList();
    }

    long currentStart = start;
    while (currentStart + duration <= end) {
        timeRanges.add(new TimeRange(currentStart, currentStart + duration));
        currentStart += duration;
    }
    if (currentStart < end) {
        timeRanges.add(new TimeRange(currentStart, end));
    }
    return timeRanges;
}

public List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();

    // Check if start and end are invalid
    if (start >= end) {
        throw new IllegalArgumentException("Start time cannot be greater than or equal to end time");
    }

    // Calculate the duration of each range
    long duration = FETCH_DATA_DURATION;
    long rangeStart = start;
    while (rangeStart < end) {
        long rangeEnd = rangeStart + duration;
        if (rangeEnd > end) {
            rangeEnd = end;
        }
        ranges.add(new TimeRange(rangeStart, rangeEnd));
        rangeStart = rangeEnd + 1;
    }

    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    // Check if start and end are valid
    if (start < 0 || end < 0) {
        throw new IllegalArgumentException("Invalid input: start and end must be greater than or equal to 0");
    }

    // Calculate the number of time ranges
    long duration = end - start;
    long numRanges = (long) Math.ceil(duration / (double) FETCH_DATA_DURATION);

    // Split the time range into numRanges
    for (int i = 0; i < numRanges; i++) {
        long startTime = start + i * FETCH_DATA_DURATION;
        long endTime = start + (i + 1) * FETCH_DATA_DURATION;
        if (endTime > end) {
            endTime = end;
        }
        timeRanges.add(new TimeRange(startTime, endTime));
    }

    return timeRanges;
}

