public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Convert the time bucket to a Date object
    Date date = new Date(timeBucket);

    // Align the re-formatted time bucket with the day step
    Calendar cal = Calendar.getInstance();
    cal.setTime(date);
    cal.add(Calendar.DAY_OF_MONTH, dayStep);

    // Convert the aligned time bucket back to a long value
    return cal.getTimeInMillis();
}

