static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep < 1) {
        throw new IllegalArgumentException("Invalid day step: " + dayStep);
    }

    if (timeBucket < 0) {
        throw new IllegalArgumentException("Invalid time bucket: " + timeBucket);
    }

    long newTimeBucket = timeBucket;
    for (int i = 0; i < dayStep; i++) {
        newTimeBucket = (newTimeBucket / 10) + (newTimeBucket % 10);
    }

    return newTimeBucket;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep == 1) {
        return timeBucket / 1000000L;
    } else if (dayStep == 11) {
        return timeBucket / 100L;
    } else {
        throw new IllegalArgumentException("dayStep must be either 1 or 11");
    }
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the re-formatted time bucket
    long reformattedTimeBucket = timeBucket - (timeBucket % dayStep) + 1;

    // Handle potential negative values
    if (reformattedTimeBucket < 0) {
        reformattedTimeBucket += Integer.MAX_VALUE;
    }

    return reformattedTimeBucket;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep < 1 || dayStep > 30) {
        throw new IllegalArgumentException("dayStep must be between 1 and 30");
    }

    int year = (int) (timeBucket / 1000000);
    int month = (int) ((timeBucket / 10000) % 100);
    int day = (int) (timeBucket % 100);

    int newDay = (day - 1) / dayStep;
    newDay = newDay * dayStep + 1;

    return year * 1000000 + (month % 100) * 10000 + newDay;
}

