        throw new IllegalArgumentException("Invalid input");
    }

    // 2. Enlarge the byte vector if necessary
    if((byteOffset + byteLength) > capacity){
        capacity = byteOffset + byteLength;
        data = Arrays.copyOf(data, capacity);
