public ByteVector putByteArray(byte[] byteArrayValue, int byteOffset, int byteLength) {
    // Check for null input
    if (byteArrayValue == null) {
        throw new NullPointerException("byteArrayValue cannot be null");
    }

    // Check for valid range of input
    if (byteOffset < 0 || byteOffset + byteLength > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset and byteLength must be within the bounds of the byte array");
    }

    // Resize byte vector if necessary
    int newCapacity = byteOffset + byteLength;
    if (newCapacity > capacity) {
        resize(newCapacity);
    }

    // Copy bytes from input array to this byte vector
    for (int i = byteOffset; i < byteOffset + byteLength; i++) {
        data[i] = byteArrayValue[i - byteOffset];
    }

    return this;
}

private void resize(int newCapacity) {
    if (newCapacity < 0) {
        throw new IllegalArgumentException("newCapacity cannot be negative");
    }
    byte[] newData = new byte[newCapacity];
    System.arraycopy(data, 0, newData, 0, Math.min(data.length, newCapacity));
    data = newData;
    capacity = newCapacity;
}

