public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) throws IOException {
    lb.clear();

    int start = 0;
    int end = 0;

    while (end < str.length()) {
        // determine the next end index of the current code point
        end = str.offsetByCodePoints(start, 1);

        int codePoint = str.codePointAt(end - 1);
        if (codePoint < 0x80) {
            lb.put((byte) codePoint);
        } else if (codePoint < 0x800) {
            lb.put((byte) (0xc0 | (codePoint >> 6)));
            lb.put((byte) (0x80 | (codePoint & 0x3f)));
        } else if (codePoint < 0xd800 || codePoint > 0xdfff) {
            lb.put((byte) (0xe0 | (codePoint >> 12)));
            lb.put((byte) (0x80 | ((codePoint >> 6) & 0x3f)));
            lb.put((byte) (0x80 | (codePoint & 0x3f)));
        } else {
            // surrogate pair
            codePoint = str.codePointAt(start);
            lb.put((byte) (0xf0 | (codePoint >> 18)));
            lb.put((byte) (0x80 | ((codePoint >> 12) & 0x3f)));
            lb.put((byte) (0x80 | ((codePoint >> 6) & 0x3f)));
            lb.put((byte) (0x80 | (codePoint & 0x3f)));
            start++;
        }

        start = end;
    }

    return lb;
}

