        if (c >= 0xD800 && c <= 0xDFFF) {
            // the char is a surrogate
            i++; // skip the next char
        }
        lb.appendByte((byte) c);
    }
    return lb;
}

public static void writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Check if the input string is null or empty
    if (str == null || str.length() == 0) {
        // If the string is null or empty, return immediately
        return;
    }

    // Get the number of bytes needed to represent the string in utf8 encoding
    final int numBytes = str.length() * 3;

    // Check if the LinkedBuffer has sufficient capacity to store the string
    if (lb.remaining() < numBytes) {
        // If the LinkedBuffer does not have sufficient capacity, expand its capacity
        lb.ensureCapacity(numBytes);
    }

    // Get the byte array from the LinkedBuffer
    final byte[] bytes = lb.array();

    // Iterate over the characters in the string
    for (int i = 0; i < str.length(); i++) {
        final char ch = str.charAt(i);

        // If the character is a letter, write its utf8 code directly
        if (ch <= 127) {
            bytes[lb.position++] = (byte) ch;
        } 
        // If the character is a special character, write its two-byte utf8 code
        else {
            bytes[lb.position++] = (byte) (0xc0 | (ch >> 6));
            bytes[lb.position++] = (byte) (0x80 | (ch & 0x3f));
        }
    }

    // Update the position of the LinkedBuffer by the number of bytes written
    lb.position(lb.position() + numBytes);
}

