    }
    // Return the LinkedBuffer
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, LinkedBuffer lb) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (session == null) {
        throw new NullPointerException("session");
    }
    if (lb == null) {
        throw new NullPointerException("lb");
    }

    final int strLen = str.length();
    final int prependable = lb.prependable();

    if (prependable == 0) {
        lb.ensureWritable(Math.max(strLen, 1024), 32);
    } else {
        lb.prependAccessibleBytes(prependable);
    }

    int i = 0;
    final byte[] ca = lb.buffer();
    final int offset = lb.offset();

    for (; i < strLen; ++i) {
        final char ch = str.charAt(i);

        if (ch <= 0x7F) {
            ca[offset + i] = (byte) ch;
        } else if (ch <= 0x7FF) {
            ca[offset + i] = (byte) (0xC0 | (ch >>> 6));
            ca[offset + i + 1] = (byte) (0x80 | (ch & 0x3F));
            i++;
        } else if (ch <= 0xD7FF || ch >= 0xE000) {
            ca[offset + i] = (byte) (0xE0 | (ch >>> 12));
            ca[offset + i + 1] = (byte) (0x80 | ((ch >>> 6) & 0x3F));
