public static String findAndSubst(String key,Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        throw new NullPointerException("Key not found in properties");
    }
    StringBuffer buffer = new StringBuffer(value);
    int i = 0;
    while (i < buffer.length()) {
        if (buffer.charAt(i) == '$') {
            if (buffer.charAt(i + 1) == '{') {
                int j = i + 2;
                while (j < buffer.length() && buffer.charAt(j) != '}') {
                    j++;
                }
                if (j < buffer.length()) {
                    String placeholder = buffer.substring(i + 2, j);
                    String replacement = props.getProperty(placeholder);
                    if (replacement != null) {
                        buffer.delete(i, j + 1);
                        buffer.insert(i, replacement);
                        i += replacement.length();
                    }
                }
            }
        }
        i++;
    }
    return buffer.toString();
}

public static String findAndSubst(String key,Properties props) {
    // Check if the key exists in the properties object
    if (props.containsKey(key)) {
        // Get the value corresponding to the key
        String value = props.getProperty(key);
        // Perform variable substitution on the value
        value = value.replaceAll("\\$\\{([^}]+)\\}", "\\$" + props.getProperty("$1"));
        return value;
    } else {
        throw new IllegalArgumentException("Key not found: " + key);
    }
}

