public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        throw new IllegalArgumentException("Key not found: " + key);
    }
    int start = value.indexOf("${");
    while (start != -1) {
        int end = value.indexOf("}", start + 1);
        if (end == -1) {
            throw new IllegalArgumentException("Unterminated variable: " + key);
        }
        String varName = value.substring(start + 2, end);
        String varValue = props.getProperty(varName);
        if (varValue == null) {
            throw new IllegalArgumentException("Variable not found: " + varName);
        }
        value = value.substring(0, start) + varValue + value.substring(end + 1);
        start = value.indexOf("${", start + 1);
    }
    return value;
}

