public static boolean endsWith(String str, String suffix, boolean ignoreCase) {
    // If the input String is null, return false
    if (str == null) {
        return false;
    }

    // If the suffix is null, return false
    if (suffix == null) {
        return false;
    }

    // If ignoreCase is set to true, convert both the input String and the suffix to lowercase
    if (ignoreCase) {
        str = str.toLowerCase();
        suffix = suffix.toLowerCase();
    }

    // Return true if the input String ends with the suffix
    return str.endsWith(suffix);
}

private static boolean endsWith(String str, String suffix, boolean ignoreCase) {
    if (str == null || suffix == null) {
        return false;
    }
    if (ignoreCase) {
        str = str.toLowerCase();
        suffix = suffix.toLowerCase();
    }
    return str.endsWith(suffix);
}

private static boolean endsWith(String str, String suffix, boolean ignoreCase) {
    if (str == null || suffix == null) {
        return false;
    }

    // Handle the case where str and suffix are equal
    if (str.equals(suffix)) {
        return true;
    }

    // Convert the suffix to lowercase if necessary
    if (!ignoreCase) {
        suffix = suffix.toLowerCase();
    }

    // Get the length of the suffix
    int suffixLength = suffix.length();

    // Get the index of the last character in the suffix
    int lastIndex = suffix.length() - 1;

    // Check if the last character in the suffix is in the str
    if (str.toLowerCase().indexOf(suffix.charAt(lastIndex)) == -1) {
        return false;
    }

    // Check if the first characters in the suffix and str match
    for (int i = 0; i < lastIndex; i++) {
        if (str.toLowerCase().charAt(str.length() - suffixLength + i) != suffix.charAt(i)) {
            return false;
        }
    }

    return true;
}

public static boolean endsWith(String str, String suffix, boolean ignoreCase) {
    if (str == null || suffix == null) {
        return false;
    }
    if (ignoreCase) {
        return str.toLowerCase().endsWith(suffix.toLowerCase());
    } else {
        return str.endsWith(suffix);
    }
}

public static boolean endsWith(String str, String suffix, boolean ignoreCase) {
    if (str == null || suffix == null) {
        return str == suffix;
    }
    int strLen = str.length();
    int suffixLen = suffix.length();
    if (suffixLen > strLen) {
        return false;
    }
    int strOffset = strLen - suffixLen;
    int suffixOffset = suffixLen - 1;
    while (suffixOffset >= 0) {
        if (ignoreCase) {
            if (Character.toLowerCase(str.charAt(strOffset)) != Character.toLowerCase(suffix.charAt(suffixOffset))) {
                return false;
            }
        } else {
            if (str.charAt(strOffset) != suffix.charAt(suffixOffset)) {
                return false;
            }
        }
        strOffset--;
        suffixOffset--;
    }
    return true;
}

