public static List<PathSegmentImpl> decodePath(URI u, boolean decode){
    // Check if the URI is null or the path component is empty
    if(u == null || u.getPath() == null || u.getPath().isEmpty()){
        return Collections.emptyList();
    }

    // Check if the path component is absolute
    boolean absolutePath = u.getPath().startsWith("/");

    // Split the path component into segments
    String[] segments = u.getPath().split("/");

    // Create a list to store the decoded path segments
    List<PathSegmentImpl> decodedSegments = new ArrayList<>(segments.length);

    // Iterate over the segments and decode them if necessary
    for(String segment : segments){
        // Check if the segment is empty
        if(segment.isEmpty()){
            continue;
        }

        // Check if the segment is valid
        if(!segment.matches("^(\\d|\\D)+$")){
            throw new IllegalArgumentException("Invalid segment: " + segment);
        }

        // Decode the segment if necessary
        String decodedSegment = decode ? URLDecoder.decode(segment, "UTF-8") : segment;

        // Add the decoded segment to the list
        decodedSegments.add(new PathSegmentImpl(decodedSegment));
    }

    return decodedSegments;
}

