    }

    // Get the existing value for the key
    Long existingValue = values.get(key);

    // If there is no existing value, set the initial value
    if (existingValue == null) {
        values.put(key, value);
    } else {
        // Accumulate the value with the existing value
        values.put(key, existingValue + value);
    }
}

