    if (descriptor.charAt(0) == '(') {
        numArgs = Type.getArgumentTypes(descriptor).length;
    }

    int numPops = 0;
    for (int i = 0; i < numArgs; i++) {
        this.pop();
        numPops++;
    }

    if (numPops != numArgs) {
        throw new IllegalStateException("pop loop failed to pop all arguments");
    }
}

