public void write(final byte[] b, final int off, final int len) throws IOException {
    // Check for null and invalid arguments
    if (b == null) {
        throw new NullPointerException("Byte array is null");
    } else if (off < 0 || len < 0 || off + len > b.length) {
        throw new IndexOutOfBoundsException("Invalid offset or length");
    }

    // Check for possible integer overflow
    if (off > Integer.MAX_VALUE - len) {
        throw new IllegalArgumentException("Offset and length are too large");
    } else if (len > Integer.MAX_VALUE - off) {
        throw new IllegalArgumentException("Offset and length are too large");
    }

    // Write the data to the internal buffer
    int remaining = len;
    int off_ = off;
    while (remaining > 0) {
        // Calculate the number of bytes to write in this iteration
        int chunk = Math.min(remaining, capacity - count);
        System.arraycopy(b, off_, buffer, count, chunk);
        count += chunk;
        remaining -= chunk;
        off_ += chunk;

        // Write to the target stream if the internal buffer is full
        if (count == capacity) {
            target.write(buffer, 0, capacity);
            count = 0;
        }
    }
}

