    // Check for valid input
    if ( b == null ) {
        throw new NullPointerException( "Input byte array is null." );
    }
    if ( off < 0 || len < 0 || ( off + len ) > b.length ) {
        throw new IndexOutOfBoundsException( "Invalid input offset/length." );
    }

    // Write to buffer
    int writeLen = Math.min( MAX_BUFFER_SIZE, len );
    int writeOff = off;
    while ( writeLen > 0 ) {
        int writeCount = write( b, writeOff, writeLen );
        if ( writeCount < 0 ) {
            // Write error
            throw new IOException( "Write error." );
        }
        writeLen -= writeCount;
        writeOff += writeCount;
    }
}

