public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    int contentSize = 0;
    try {
        // Calculate the total content size of the buffer
        while (node != null) {
            contentSize += node.size();
            node = node.next;
        }
        // Write the buffer content to the output
        node = head;
        while (node != null) {
            node.writeTo(out);
            node = node.next;
        }
    } finally {
        // Close the output stream to release any resources
        out.close();
    }
    return contentSize;
}

