public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {

        // Validate input
        if (out == null) {
            throw new IllegalArgumentException("DataOutput cannot be null");
        }
        if (node == null) {
            throw new IllegalArgumentException("LinkedBuffer cannot be null");
        }

        // Calculate the total size of the buffer
        int totalSize = 0;
        LinkedBuffer currNode = node;
        while (currNode != null) {
            totalSize += currNode.getChunkLength();
            currNode = currNode.getNextNode();
        }

        // Write the data to the output
        currNode = node;
        while (currNode != null) {
            out.write(currNode.getChunk());
            currNode = currNode.getNextNode();
        }

        return totalSize;
    }

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    // Edge case handling
    if (node == null) {
        throw new IllegalArgumentException("Node cannot be null.");
    }

    // Write the node's content
    int contentSize = 0;
    for (LinkedBuffer child : node.getChildren()) {
        contentSize += writeTo(out, child);
    }

    // Write the node's data
    out.writeInt(node.getData());
    contentSize++;

    return contentSize;
}

