        throw new IllegalArgumentException("end index out of bounds");
    }

    // Iterate over the types in the frame and put them in the stack map table entries
    for (int i = start; i < end; i++) {
        // Get the type of the ith element in the frame
        VerificationTypeInfo type = currentFrame.get(i);

        // Put the type in the stack map table entries
        stackMapTableEntries.put(offset, type);
    }
}

private void putAbstractTypes(int start, int end) {
    for (int i = start; i < end; i++) {
        int tag = -1;
        int o = currentFrame[i];
        if (o == null) {
            tag = VerificationTypeInfo.Top.tag;
        } else {
            switch (o.getClass().getName()) {
                case "Integer":
                    tag = VerificationTypeInfo.Integer.tag;
                    break;
                case "Long":
                    tag = VerificationTypeInfo.Long.tag;
                    break;
                case "Float":
                    tag = VerificationTypeInfo.Float.tag;
                    break;
                case "Double":
                    tag = VerificationTypeInfo.Double.tag;
                    break;
                case "Reference":
                    tag = VerificationTypeInfo.Object.tag;
                    break;
            }
        }
        if (tag == -1) {
            throw new RuntimeException("Invalid abstract type in frame");
        }
        stackMapTableEntries.add(new StackMapTableEntry(tag));
    }
}

