@Override
protected Character convertToType(final Object value) throws Exception {
    if (value == null) {
        return null;
    }

    if (value instanceof Character) {
        return (Character) value;
    }

    if (value instanceof String) {
        if (((String) value).length() != 1) {
            throw new IllegalArgumentException("Value must be a single-character string");
        }
        return ((String) value).charAt(0);
    }

    if (value instanceof Number) {
        return (char) (int) value;
    }

    throw new IllegalArgumentException("Cannot convert " + value.getClass().getName() + " to Character");
}

@Override
protected Character convertToType(Class<?> type, Object value) throws Exception {
    if (type.isInstance(value)) {
        return (Character) value;
    }

    if (value instanceof Number) {
        return (char) ((Number) value).intValue();
    }

    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        }
    }

    throw new Exception("Cannot convert value " + value + " to type Character");
}

