public static int nextPrime(int desiredCapacity) {
    // Step 1: Check if the input is valid
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("Invalid input: Desired capacity must be a positive integer.");
    }

    // Step 2: Initialize a variable to hold the closest prime number that is >= desiredCapacity
    int closestPrime = desiredCapacity;

    // Step 3: Iterate through the prime numbers starting from 3 (the first prime number)
    for (int i = 3; i <= desiredCapacity; i += 2) {
        // Step 4: Check if the current number is a prime number
        if (isPrime(i)) {
            // Step 5: If the current number is prime, check if it is closer to the desired capacity than the current closest prime
            if (Math.abs(i - desiredCapacity) < Math.abs(closestPrime - desiredCapacity)) {
                // Step 6: If the current number is closer to the desired capacity, update the closest prime
                closestPrime = i;
            }
        }
    }

    // Step 7: Return the closest prime number that is >= desiredCapacity
    return closestPrime;
}

private static boolean isPrime(int number) {
    // Step 4: Check if the number is divisible by 2
    if (number % 2 == 0) {
        return false;
    }

    // Step 5: Iterate from 3 to the square root of the number
    for (int i = 3; i <= Math.sqrt(number); i += 2) {
        // Step 6: Check if the number is divisible by any other number in the range
        if (number % i == 0) {
            return false;
        }
    }

    // Step 7: If the number is not divisible by any other number in the range, return true
    return true;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("Invalid argument: desiredCapacity must be non-negative");
    }

    // Check if the desired capacity is prime
    boolean isDesiredCapacityPrime = true;
    for (int i = 2; i <= Math.sqrt(desiredCapacity); i++) {
        if (desiredCapacity % i == 0) {
            isDesiredCapacityPrime = false;
            break;
        }
    }

    // If the desired capacity is prime, return it
    if (isDesiredCapacityPrime) {
        return desiredCapacity;
    }

    // Find the next prime number greater than the desired capacity
    int prime = desiredCapacity + 1;
    while (true) {
        boolean isPrime = true;
        for (int i = 2; i <= Math.sqrt(prime); i++) {
            if (prime % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return prime;
        }
        prime++;
    }
}

public static int nextPrime(int desiredCapacity) {
    // Check if the desired capacity is invalid
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("Desired capacity must be a positive integer");
    }

    // Check if the desired capacity is already a prime number
    if (isPrime(desiredCapacity)) {
        return desiredCapacity;
    }

    // Initialize the upper and lower bounds of the range
    int lowerBound = 1;
    int upperBound = Math.max(desiredCapacity, 1000);

    // Search for the next prime number in the range
    while (lowerBound < upperBound) {
        int primeCandidate = (lowerBound + upperBound) / 2;
        if (isPrime(primeCandidate)) {
            return primeCandidate;
        } else if (primeCandidate < desiredCapacity) {
            lowerBound = primeCandidate + 1;
        } else {
            upperBound = primeCandidate - 1;
        }
    }

    // If no prime number is found in the range, return the upper bound
    return upperBound;
}

private static boolean isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    if (n == 2 || n == 3) {
        return true;
    }
    if (n % 2 == 0 || n % 3 == 0) {
        return false;
    }
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

