    if(desiredCapacity <= 0){
        throw new IllegalArgumentException("Desired capacity must be a positive integer.");
    }
    int currentPrime = 2;
    while(currentPrime < desiredCapacity){
        currentPrime++;
        if(isPrime(currentPrime)){
            return currentPrime;
        }
    }
    return currentPrime;
}

private static boolean isPrime(int number){
    if(number <= 1){
        return false;
    }
    for(int i = 2; i < number; i++){
        if(number % i == 0){
            return false;
        }
    }
    return true;
}

