    // Check if the desired capacity is greater than or equal to 30
    if (desiredCapacity >= 30) {
        // If the desired capacity is greater than or equal to 30,
        // calculate the next prime number that is within 11% of
        // the desired capacity
        double nextPrime = Math.ceil(desiredCapacity / 0.9);
        return (int) nextPrime;
    } else {
        // If the desired capacity is not greater than or equal to 30,
        // return the desired capacity
        return desiredCapacity;
    }
}

