}

public static String trimTrailingWhitespace(String str) {
    if (str == null || str.isEmpty()) {
        return str;
    }
    // Find the last non-whitespace character in the string
    int lastNonWhitespaceIndex = str.length() - 1;
    for (int i = lastNonWhitespaceIndex; i >= 0; i--) {
        if (!Character.isWhitespace(str.charAt(i))) {
            lastNonWhitespaceIndex = i;
            break;
        }
    }
    // If the last character is a whitespace character, return the substring of the string up to that point
    if (lastNonWhitespaceIndex == str.length() - 1 && Character.isWhitespace(str.charAt(lastNonWhitespaceIndex))) {
        return str.substring(0, lastNonWhitespaceIndex + 1);
    }
    return str;
}

public static String trimTrailingWhitespace(String str) {
    // Check if the input String is null or empty
    if (str == null || str.isEmpty()) {
        return str;
    }

    // Trim the trailing whitespace from the input String
    int endIndex = str.length() - 1;
    while (endIndex >= 0 && Character.isWhitespace(str.charAt(endIndex))) {
        endIndex--;
    }
    return str.substring(0, endIndex + 1);
}

