private static int digitValue(final char c) {
    if (!Character.isDigit(c)) {
        throw new IllegalArgumentException("Not a digit: " + c);
    }

    int value = Character.digit(c, 36);
    if (value == 0) {
        if ('a' <= c && c <= 'z') {
            value = c - 'a' + 10;
        } else if ('A' <= c && c <= 'Z') {
            value = c - 'A' + 10;
        }
    }
    return value;
}

