    if (mapping == null) {
        return false;
    }

    return atmosphereHandlers.remove(mapping) != null;
}

public boolean removeAtmosphereHandler(String mapping) {
    // Check if the given mapping is valid
    if (mapping == null || mapping.isEmpty()) {
        throw new IllegalArgumentException("Mapping cannot be null or empty");
    }

    // Find the handler associated with the given mapping
    AtmosphereHandler handler = atmosphereHandlers.get(mapping);

    // Check if the handler exists
    if (handler == null) {
        return false;
    }

    // Remove the handler from the framework
    atmosphereHandlers.remove(mapping);

    // Disconnect any pending handlers
    // Note: This is necessary because Atmosphere handles connections asynchronously,
    // so we need to wait for the disconnection to be acknowledged
    handler.disconnect(true);

    return true;
}

