public boolean removeAtmosphereHandler(String mapping) {
    // Step 1: Validate input
    if (mapping == null || mapping.isEmpty()) {
        throw new IllegalArgumentException("Mapping cannot be null or empty");
    }

    // Step 2: Check if the AtmosphereHandler exists
    if (!atmosphereHandlers.containsKey(mapping)) {
        return false;
    }

    // Step 3: Get the AtmosphereHandler and remove it from the map
    AtmosphereHandler atmosphereHandler = atmosphereHandlers.remove(mapping);

    // Step 4: Unregister the AtmosphereHandler from Jetty
    try {
        atmosphereHandlerRegistrations.remove(atmosphereHandler);
    } catch (IllegalStateException e) {
        // Ignore, handler was already unregistered
    }

    // Step 5: Return true to indicate successful removal
    return true;
}

public byte[] toByteArray() {
	// Create a new byte array to hold the contents of the buffer(s)
	byte[] byteArray = new byte[getTotalLength()];
	// Copy the contents of the buffer(s) into the byte array
	int offset = 0;
	for (Buffer buffer : buffers) {
		System.arraycopy(buffer.getContent(), 0, byteArray, offset, buffer.getLength());
		offset += buffer.getLength();
	}
	// Return the byte array
	return byteArray;
}

public byte[] toByteArray() {
    List<byte[]> bufferList = new ArrayList<>();

    for (var buffer: buffers) {
        bufferList.add(buffer);
    }

    int totalLength = 0;
    for (byte[] buffer: bufferList) {
        totalLength += buffer.length;
    }

    byte[] result = new byte[totalLength];
    int offset = 0;
    for (byte[] buffer: bufferList) {
        System.arraycopy(buffer, 0, result, offset, buffer.length);
        offset += buffer.length;
    }

    return result;
}

public final byte[] toByteArray() {
    // Create a list to store the data written to the buffer(s)
    List<byte[]> data = new ArrayList<>();

    // Add the data written to the output stream(s) to the list
    for (OutputStream os : outputStreams) {
        data.add(os.toByteArray());
    }

    // Concatenate the data from all streams into a single byte array
    byte[] result = new byte[0];
    for (byte[] d : data) {
        result = ArrayUtils.addAll(result, d);
    }

    // Return the concatenated byte array
    return result;
}

public byte[] toByteArray() {
    int size = 0;
    for (ByteBuffer buffer : buffers) {
        size += buffer.remaining();
    }

    byte[] result = new byte[size];
    int offset = 0;
    for (ByteBuffer buffer : buffers) {
        int remaining = buffer.remaining();
        buffer.get(result, offset, remaining);
        offset += remaining;
    }

    return result;
}

