public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder builder = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\' && i < str.length() - 1) {
            char nextChar = str.charAt(i + 1);
            if (nextChar == 'n') {
                builder.append('\n');
                i++;
            } else if (nextChar == 't') {
                builder.append('\t');
                i++;
            } else {
                builder.append(c);
            }
        } else {
            builder.append(c);
        }
    }
    return builder.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    // Create a new StringBuilder to build the output
    StringBuilder sb = new StringBuilder(str.length());

    // Iterate over the characters in the input String
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);

        // If the current character is a backslash, check if it is followed by another backslash or a newline
        if (c == '\\') {
            // If the backslash is followed by another backslash, add it to the output as-is
            if (i + 1 < str.length() && str.charAt(i + 1) == '\\') {
                sb.append('\\');
                i++;
            // If the backslash is followed by a newline, add a newline character to the output
            } else if (i + 1 < str.length() && str.charAt(i + 1) == 'n') {
                sb.append('\n');
                i++;
            // If the backslash is not followed by another backslash or a newline, throw an Exception
            } else {
                throw new Exception("Invalid escape sequence in input String");
            }
        // If the current character is not a backslash, add it to the output as-is
        } else {
            sb.append(c);
        }
    }

    return sb.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    int sz = str.length();
    StringBuilder buffer = new StringBuilder(sz);
    String unescapedStr = null;
    int lastPeekedChar = 0;
    for (int i = 0; i < sz; i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            char nextChar = (i + 1 < sz) ? str.charAt(i + 1) : 0;
            if (nextChar == '\\') {
                // Handle escape character
                buffer.append('\\');
                i++;
            } else if (nextChar == 'n') {
                // Handle newline character
                buffer.append('\n');
                i++;
            } else {
                // Handle invalid escape sequence
                throw new Exception("Invalid escape sequence: \\" + nextChar);
            }
        } else {
            buffer.append(ch);
        }
        lastPeekedChar = ch;
    }
    unescapedStr = buffer.toString();
    return unescapedStr;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuffer sb = new StringBuffer();
    char[] s = str.toCharArray();
    for (int i = 0; i < s.length; i++) {
        char c = s[i];
        switch (c) {
            case '\\':
                sb.append('\\');
                break;
            case 'n':
                sb.append('\n');
                break;
            case 't':
                sb.append('\t');
                break;
            case 'b':
                sb.append('\b');
                break;
            case 'f':
                sb.append('\f');
                break;
            case 'r':
                sb.append('\r');
                break;
            case '"':
                sb.append('"');
                break;
            case '\'':
                sb.append('\'');
                break;
            default:
                if (c == '\\' && i < s.length - 1) {
                    i++;
                    if (s[i] == 'u') {
                        sb.append((char) Integer.parseInt(str.substring(i + 1, i + 5), 16));
                        i += 4;
                    } else {
                        sb.append(c);
                    }
                } else {
                    sb.append(c);
                }
                break;
        }
    }
    return sb.toString();
}

private static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder builder = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            i++;
            char nextChar = str.charAt(i);
            switch (nextChar) {
                case 'n':
                    builder.append('\n');
                    break;
                case 'r':
                    builder.append('\r');
                    break;
                case 't':
                    builder.append('\t');
                    break;
                case 'b':
                    builder.append('\b');
                    break;
                case 'f':
                    builder.append('\f');
                    break;
                case '\'':
                    builder.append('\'');
                    break;
                case '"':
                    builder.append('"');
                    break;
                case '\\':
                    builder.append('\\');
                    break;
                default:
                    throw new Exception("Unrecognized escape character: " + nextChar);
            }
        } else {
            builder.append(c);
        }
    }

    return builder.toString();
}

public static String javaCharset(String charset) {
    switch (charset.toUpperCase()) {
        case "US-ASCII":
            return "ASCII";
        case "UTF-8":
            return "UTF8";
        case "UTF-16":
            return "Unicode";
        case "UTF-16BE":
            return "UnicodeBig";
        case "UTF-16LE":
            return "UnicodeLittle";
        default:
            return charset;
    }
}

static String javaCharset(String charset){
    if (charset.equalsIgnoreCase("us-ascii")){
      return "UTF-8";
    } else if (charset.equalsIgnoreCase("iso-8859-1")){
      return "ISO-8859-1";
    } else if (charset.equalsIgnoreCase("utf-8")){
