    } else if (charset.equalsIgnoreCase("utf-16be")){
      return "UnicodeBig";
    } else if (charset.equalsIgnoreCase("utf-16le")){
      return "UnicodeLittle";
    } else if (charset.equalsIgnoreCase("utf-32be")){
      return "UTF-32";
    } else if (charset.equalsIgnoreCase("utf-32le")){
      return "UTF-32";
    } else {
      return "";
    }
  }

