public ListNode<E> previousNode() {
    // Check if the previous node exists
    if (previous == null) {
        return null;
    }
    // Return the previous node
    return previous;
}

public ListNode<E> previousNode() {
    if (this.previous == null) {
        return null;
    }
    return this.previous;
}

public ListNode<E> previousNode() {
    // If the current node is the head node, return null
    if (this == head) {
        return null;
    }

    // Find the previous node by traversing the list in reverse order
    ListNode<E> previousNode = null;
    for (ListNode<E> node = head; node != null; node = node.next) {
        if (node.next == this) {
            previousNode = node;
            break;
        }
    }

    // Return the previous node
    return previousNode;
}

