public short readShort(final int offset) {
    // Check if the offset is out of bounds
    if (offset < 0 || offset >= this.data.length - 1) {
        throw new IndexOutOfBoundsException("Offset out of bounds: " + offset);
    }

    // Read the value from the data array
    int value = ((this.data[offset] & 0xFF) << 8) | (this.data[offset + 1] & 0xFF);

    // Check for any potential sign extension issues
    if (value >= 0x8000) {
        value -= 0x10000;
    }

    return (short) value;
}

public short readShort(int offset) {
    // Check if the offset is within the bounds of the class file
    if (offset < 0 || offset >= length) {
        throw new IndexOutOfBoundsException("Offset " + offset + " is not within the bounds of the class file");
    }

    // Check if the value is a valid signed short
    final Short value = readShort(buffer, offset);
    if (value == null) {
        throw new RuntimeException("Invalid value for short at offset " + offset);
    }

    return value;
}

private static Short readShort(byte[] buffer, int offset) {
    final int value = (buffer[offset] & 0xff) << 8 | (buffer[offset + 1] & 0xff);
    // Check if the value is within the range of a signed short
    if (value < Short.MIN_VALUE || value > Short.MAX_VALUE) {
        return null;
    }
    return (short) value;
}

public short readShort(int offset) {
    // Check if the offset is valid
    if (offset < 0 || offset > classReader.length - Short.BYTES) {
        throw new IllegalArgumentException("Invalid offset");
    }

    // Read the short value from the class reader
    try {
        return classReader.readShort(offset);
    } catch (IOException e) {
        throw new IllegalArgumentException("Unable to read short value");
    }
}

public static Object[] copyArrayGrow1(Object[] array, Class<?> newArrayComponentType) {
    if (array == null) {
        return createEmptyArrayOfType(newArrayComponentType, 1);
    }

    Object[] result = Arrays.copyOf(array, array.length + 1);
    Arrays.fill(result, array.length, result.length, null);
    return result;
}

private static <T> T[] createEmptyArrayOfType(Class<T> componentType, int size) {
    return (T[]) Array.newInstance(componentType, size);
}

private static Object copyArrayGrow1(final Object array,final Class<?> newArrayComponentType) {
    // Step 1: Define an empty array to hold the copied values
    final Object[] copiedArray = (Object[]) Array.newInstance(newArrayComponentType, array.length + 1);

    // Step 2: Copy the values from the input array into the copied array
    System.arraycopy(array, 0, copiedArray, 0, array.length);

    // Step 3: Add the default value to the end of the copied array
    copiedArray[copiedArray.length - 1] = null;

    // Step 4: Return the copied and grown array
    return copiedArray;
}

public static Object copyArrayGrow1(Object array, Class<?> newArrayComponentType) {
    if (array == null) {
        array = Array.newInstance(newArrayComponentType, 1);
    } else {
        Object newArray = Array.newInstance(array.getClass().getComponentType(), array.length + 1);
        System.arraycopy(array, 0, newArray, 0, array.length);
        array = newArray;
    }
    return array;
}

public static Object copyArrayGrow1(Object array, Class<?> newArrayComponentType) {
    Object newArray;
    if (array == null) {
        newArray = Array.newInstance(newArrayComponentType, 1);
    } else {
        newArray = Arrays.copyOf(array, Array.getLength(array) + 1);
    }
    return newArray;
}

public static Object copyArrayGrow1(Object array, Class<?> newArrayComponentType) {
    if (array == null) {
        return Array.newInstance(newArrayComponentType, 1);
    }

    int size = Array.getLength(array);
    Object newArray = Array.newInstance(newArrayComponentType, size + 1);

    for (int i = 0; i < size; i++) {
        Array.set(newArray, i, Array.get(array, i));
    }

    return newArray;
}

public int computeBinaryLog(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }

    int result = 0;
    while (n > 0) {
        n = n >> 1;
        result++;
    }

    return result;
}

public int computeBinaryLog(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }

    int log = 0;
    while (n > 0) {
        n >>= 1;
        log++;
    }
    return log;
}

public static int computeBinaryLog(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int result = 0;
    while (n > 1) {
        n = n >> 1;
        result++;
    }
    return result;
}

public int computeBinaryLog(int n) {
    int logValue = 0;
    while (n > 0) {
        logValue++;
        n >>= 1;
    }
    return logValue;
}

private int computeBinaryLog(int n) {
    if (n == 0) {
        throw new IllegalArgumentException("n must be greater than 0");
    }

    int log = 0;
    while (n > 1) {
        log++;
        n >>= 1;
    }

    return log;
}

private Set<V> intersection(Set<V> set1, Set<V> set2) {
    // Handle invalid inputs
    if (set1 == null || set2 == null) {
        throw new IllegalArgumentException("Input sets cannot be null");
