    return unusedNodes;
}

protected int removeUnusedNodes(){
    // Iterate through the nodes in the Category tree
    for (Node node : getNodes()){
        // Check if the node is inactive
        if (!node.isActive()){
            // Remove the node from the tree
            removeNode(node);
        }
    }
    return getNodeCount();
}

int removeUnusedNodes(){
  // Create a set to keep track of active nodes
  Set<Node> activeNodes = new HashSet<>();

  // Iterate through the root node and its descendants
  for (Node node : getRootNodes()) {
    // If the node is not active, skip it
    if (!node.isActive()) continue;

    // Add the active node and its descendants to the active nodes set
    activeNodes.add(node);
    addDescendantNodes(activeNodes, node);
  }

  // Iterate through all the nodes in the graph
  for (Node node : getAllNodes()) {
    // If the node is not in the active nodes set, mark it as inactive
    if (!activeNodes.contains(node)) node.setActive(false);
  }

  // Return the number of active nodes
  return activeNodes.size();
}

void addDescendantNodes(Set<Node> activeNodes, Node node){
  // If the node has no descendants, return
  if (node.getChildNodes().isEmpty()) return;

  // Add the node's descendants to the active nodes set
  for (Node child : node.getChildNodes()) {
    activeNodes.add(child);
    addDescendantNodes(activeNodes, child);
  }
}

private int removeUnusedNodes() {
  int count = 0;
  for (CategoryTreeNode node : nodes) {
    if (!node.isActive()) {
      removeNode(node);
      count++;
    }
  }
  return count;
}

protected int removeUnusedNodes() {
    // Build a set of active node IDs
    Set<Integer> activeNodes = new HashSet<>();
    for (CategoryNode node : nodes) {
        if (node.isActive()) {
            activeNodes.add(node.getId());
        }
    }

    // Iterate over all nodes and remove any inactive nodes
    int numRemoved = 0;
    for (int i = 0; i < nodes.size(); i++) {
        CategoryNode node = nodes.get(i);
        if (!activeNodes.contains(node.getId())) {
            nodes.remove(i);
            numRemoved++;
            i--; // Decrement i since the list size has changed
        }
    }

    return numRemoved;
}

