private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Step 1: Find the first node that satisfies the predicate
    Node current = start;
    while (!predicate.test(current)) {
        current = getAdjacentNode(current, dir);
        if (current == stop) {
            // If the predicate is not satisfied for the entire component, return a circulator to the stop node
            return new OuterFaceCirculator(Collections.singletonList(stop), null);
        }
    }

    // Step 2: Find the first node that does not satisfy the predicate
    Node previous = current;
    while (predicate.test(current)) {
        current = getAdjacentNode(current, dir);
        if (current == stop) {
            // If the predicate is not satisfied for the entire component, return a circulator to the stop node
            return new OuterFaceCirculator(Collections.singletonList(stop), null);
        }
    }

    // Step 3: Return a circulator to the node that satisfied the predicate and the previous node
    return new OuterFaceCirculator(Arrays.asList(previous, current), previous);
}

