private static int compareSigned(long a, long b) {
    // If a is negative, and b is not, a is less than b
    if (a < 0 && b >= 0) {
        return -1;
    }
    // If a is not negative, and b is negative, a is greater than b
    else if (a >= 0 && b < 0) {
        return 1;
    }
    // If a and b are the same sign, compare them as normal
    else {
        return Long.compare(a, b);
    }
}

else if (a >= 0 && b < 0) {
        return 1;
