private static int compareSigned(long a, long b) {
    // Check for negative zero
    if (a == -0.0 && b == -0.0) {
        return 0;
    }
    // Check for equality
    if (a == b) {
        return 0;
    }
    // Check for greater than
    if (a > b) {
        return 1;
    }
    // Check for less than
    if (a < b) {
        return -1;
    }
    // Check for NaN
    if (Double.isNaN(a) || Double.isNaN(b)) {
        throw new IllegalArgumentException("Input must not be NaN");
    }
    // Check for infinity
    if (Double.isInfinite(a) ^ Double.isInfinite(b)) {
        return (Double.isInfinite(a) ? 1 : -1);
    }
    // Check for smaller mantissa
    long diff = a - b;
    if (diff != 0) {
        return (diff > 0 ? 1 : -1);
    }
    // Check for smaller exponent
    int diff = Double.doubleToLongBits(a) & DOUBLE_EXP_BIT_MASK;
    diff -= (Double.doubleToLongBits(b) & DOUBLE_EXP_BIT_MASK);
    if (diff != 0) {
        return (diff > 0 ? 1 : -1);
    }
    return 0;
}

