public final MatchResult match(CharSequence uri) {
    if (uri == null) {
        throw new IllegalArgumentException("uri cannot be null");
    }

    int[][] dp = new int[uri.length() + 1][pattern.length() + 1];
    dp[0][0] = 1;

    for (int i = 1; i <= uri.length(); i++) {
        for (int j = 1; j <= pattern.length(); j++) {
            if (uri.charAt(i - 1) == pattern.charAt(j - 1)) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }

    MatchResult result = new MatchResult();
    result.setMatched(dp[uri.length()][pattern.length()] > 0);

    if (result.isMatched()) {
        result.setStartIndex(dp[uri.length()][pattern.length()] - 1 - dp[uri.length() - dp[uri.length()][pattern.length()]][pattern.length() - 1]);
        result.setEndIndex(uri.length());
    }

    return result;
}

public final MatchResult match(CharSequence uri) {
    // Initialize the match result
    MatchResult matchResult = new MatchResult();

    // Get the pattern parts
    List<String> patternParts = Arrays.asList(getPattern().split("/"));

    // Get the URI parts
    List<String> uriParts = Arrays.asList(uri.toString().split("/"));

    // Iterate over the pattern parts
    for (int i = 0; i < patternParts.size(); i++) {
        // Get the current pattern part
        String patternPart = patternParts.get(i);

        // Check if the pattern part is a wildcard
        if (patternPart.equals("*")) {
            // Add the URI part to the match result
            matchResult.addURIPart(uriParts.get(i));
        } else {
            // Check if the pattern part matches the URI part
            if (!patternPart.equals(uriParts.get(i))) {
                // Return null if the pattern part does not match the URI part
                return null;
            }
        }
    }

    // Return the match result
    return matchResult;
}

public static byte convertHexDigit(byte b) {
    if (b >= 0x30 && b <= 0x39) {
        return b - 0x30;
    } else if (b >= 0x41 && b <= 0x46) {
        return b - 0x37;
    } else {
        throw new IllegalArgumentException("Invalid hex digit: " + (char)b);
    }
}

public static byte convertHexDigit(byte b) {
    // Handle invalid input
    if (b < 0 || b > 0xff) {
        throw new IllegalArgumentException("Invalid input byte");
    }

    // Convert the byte to hex
    int val = b;
    if (val >= 0x30 && val <= 0x39) {
        // Digit 0-9
        val -= 0x30;
    } else if (val >= 0x41 && val <= 0x46) {
        // Character A-F
        val -= 0x37;
    } else if (val >= 0x61 && val <= 0x66) {
        // character a-f
        val -= 0x57;
    } else {
        // Invalid input
        throw new IllegalArgumentException("Invalid input byte");
    }

    // Return the byte value
    return (byte) val;
}

