        for (int i = 0; i < shardingKeyIndices.length - 1; i++) {
            if (Integer.parseInt(shardingKeyIndices[i]) + 1 != Integer.parseInt(shardingKeyIndices[i + 1])) {
                throw new IllegalStateException("Sharding key indices are not continuous");
            }
        }
    }
}

