private void check(String modelName) throws IllegalStateException {
    Map<Integer, String> shardingKeyIndices = getShardingKeyIndices(modelName);
    if (shardingKeyIndices.isEmpty()) {
        throw new IllegalStateException("Sharding key indices are not set for " + modelName);
    }
    int[] indices = new int[shardingKeyIndices.size()];
    int index = 0;
    for (Integer key : shardingKeyIndices.keySet()) {
        indices[index++] = key;
    }
    if (indices.length > 1) {
        Arrays.sort(indices);
        for (int i = 1; i < indices.length; i++) {
            if (indices[i] - indices[i - 1] != 1) {
                throw new IllegalStateException("Sharding key indices are not continuous for " + modelName);
            }
        }
    }
}

public byte readByte() throws IOException {
    // Check if there is still data available in the buffer
    if (buffer.hasRemaining()) {
        // Return the next byte from the buffer
        return buffer.get();
    } else {
        // Refill the buffer
        fillBuffer();

        // If the buffer is still empty, throw an IOException
        if (!buffer.hasRemaining()) {
            throw new IOException("No more data available");
        }

        // Return the next byte from the buffer
        return buffer.get();
    }
}

