public static void register(Object value) {
    if (value == null) {
        return;
    }

    if (value instanceof Class) {
        Class<?> clazz = (Class<?>) value;
        synchronized (CLASS_REGISTRY) {
            CLASS_REGISTRY.put(clazz, null);
        }
    } else if (value instanceof Method) {
        Method method = (Method) value;
        Class<?> declaringClass = method.getDeclaringClass();
        synchronized (METHOD_REGISTRY) {
            METHOD_REGISTRY.put(method, declaringClass);
        }
    } else {
        throw new IllegalArgumentException("Invalid object type: " + value.getClass());
    }
}

