protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour.isEmpty()) {
        throw new IllegalArgumentException("Tour is empty");
    }
    if (graph == null) {
        throw new IllegalArgumentException("Graph is null");
    }

    // Get the starting vertex of the tour
    E firstEdge = tour.iterator().next();
    Vertex<V> startVertex = graph.getVertex(firstEdge.getStartVertex());

    // Get the ending vertex of the tour
    E lastEdge = tour.iterator().next();
    Vertex<V> endVertex = graph.getVertex(lastEdge.getEndVertex());

    // Construct the path
    GraphPath<V, E> path = new GraphPath<>();
    path.addVertex(startVertex);
    path.addEdge(firstEdge);
    for (int i = 1; i < tour.size() - 1; i++) {
        E edge = tour.get(i);
        Vertex<V> tempVertex = graph.getVertex(edge.getEndVertex());
        path.addVertex(tempVertex);
        path.addEdge(edge);
    }
    path.addVertex(endVertex);

    return path;
}

public GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Step 1: Check for invalid inputs
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Step 2: Initialize the graph path
    GraphPath<V, E> path = new GraphPath<V, E>(graph.vertices);

    // Step 3: Iterate over the edges in the tour
    for (E edge : tour) {
        // Step 4: Add the edge to the graph path
        path.addEdge(edge);
    }

    // Step 5: Return the completed graph path
    return path;
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Step 1: Check if the input is valid
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Step 2: Create a new graph path with the same vertices as the graph
    GraphPath<V, E> path = new GraphPath<>(graph.vertices(), graph.getEdgeInitialCapacity());

    // Step 3: Iterate over the edges in the tour and add them to the path
    for (E edge : tour) {
        if (!graph.containsEdge(edge)) {
            throw new IllegalArgumentException("Invalid edge");
        }
        path.addEdge(edge);
    }

    // Step 4: Return the path
    return path;
}

def edgeSetToTour(tour: Set[E], graph: Graph[V, E]): GraphPath[V, E] = {
    // Check if the input set is empty
    if (tour.isEmpty)
      throw new IllegalArgumentException("The input set must contain at least one edge")

    // Create a new graph path
    val path = new GraphPath[V, E]

    // Set the start vertex
    val startVertex = tour.head
    path.addVertex(startVertex)

    // Set the edges of the path by iterating over the tour set
    for (edge <- tour.tail) {
      // Check if the edge is valid
      if (!graph.containsEdge(edge) || !edge.getSourceVertex.equals(startVertex))
        throw new IllegalArgumentException("The edge " + edge + " is not valid")

      // Add the edge to the path
      path.addEdge(edge)

      // Update the start vertex for the next edge
      startVertex = edge.getDestinationVertex
    }

    // Return the completed graph path
    path
  }

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Initialize the graph path
    GraphPath<V, E> path = new GraphPath<>();

    // Iterate over the edges in the tour
    for (E edge : tour) {
        // Get the source and target vertices of the edge
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        // Add the edge to the path
        path.addEdge(edge);

        // Add the vertices to the path (if not already added)
        if (!path.containsVertex(source)) {
            path.addVertex(source);
        }
        if (!path.containsVertex(target)) {
            path.addVertex(target);
        }
    }

    // Return the graph path
    return path;
}

