public int addConstantNameAndType(String name, String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 0; i < constantPool.size(); i++) {
        ConstantInfo constant = constantPool.get(i);
        if (constant instanceof ConstantNameAndTypeInfo && constant.getName().equals(name) && constant.getDescriptor().equals(descriptor)) {
            // Return the index of the existing constant
            return i;
        }
    }

    // Create a new ConstantNameAndTypeInfo and add it to the constant pool
    ConstantNameAndTypeInfo constant = new ConstantNameAndTypeInfo(name, descriptor);
    constantPool.add(constant);

    // Return the index of the new constant
    return constantPool.size() - 1;
}

public Symbol addConstantNameAndType(String name, String descriptor) {
    if (name == null || descriptor == null) {
        throw new NullPointerException("Name and descriptor must not be null");
    }
    // check if the constant pool already contains a similar item
    for (Symbol symbol : this.constants) {
        if (symbol.getName().equals(name) && symbol.getDescriptor().equals(descriptor)) {
            return symbol;
        }
    }
    // create a new symbol and add it to the constant pool
    Symbol symbol = new Symbol(name, descriptor, this.getConstantPoolIndex(this.constants.size()));
    this.constants.add(symbol);
    return symbol;
}

