    }

    // Step 2: Check if the constant pool already contains a similar item
    for (ConstantPoolEntry entry : constantPool) {
        if (entry instanceof ConstantNameAndType && entry.getName().equals(name) && entry.getDescriptor().equals(descriptor)) {
            return entry.getIndex();
        }
    }

    // Step 3: Create a new ConstantNameAndType and add it to the constant pool
    ConstantNameAndType newEntry = new ConstantNameAndType(name, descriptor);
