    Symbol newSymbol = new Symbol(Symbol.Type.CONSTANT_NameAndType_info, name, descriptor);
    this.constant_pool.add(newSymbol);
    return newSymbol;
}

public String unescapeId(String input) {
    StringBuilder output = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            i++;
            c = input.charAt(i);
            if (c == 't') {
                output.append('\t');
            } else if (c == 'r') {
                output.append('\r');
            } else if (c == 'n') {
                output.append('\n');
            } else if (c == '\\') {
                output.append('\\');
            } else if (c == '0') {
                output.append('\0');
            } else {
                throw new IllegalArgumentException("Invalid escape sequence: \\" + c);
            }
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

public static String unescapeId(String input) {
    // Check for null input
    if (input == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }

    // Create a new string builder with the same capacity as the input
    StringBuilder output = new StringBuilder(input.length());

    // Iterate over each character in the input string
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);

        // Check if the character is a backslash
        if (c == '\\') {
            // Check if the next character is a backslash or a zero
            if (i < input.length() - 1 && input.charAt(i + 1) == '\\' || input.charAt(i + 1) == '0') {
                // Append the next character without any modifications
                output.append(input.charAt(i + 1));
                // Increment the index to skip the next character
                i++;
            } else {
                // Append the backslash character
                output.append('\\');
            }
        } else {
            // Append the current character
            output.append(c);
        }
    }

    // Return the unescaped output string
    return output.toString();
}

