private String hash(){
    int hash = 0;
    for (Row row : this.getRows()){
        for (Column column : row.getColumns()){
            switch(column.getType()){
                case VARCHAR:
                    hash += column.getVarcharValue().hashCode();
                    break;
                case INT:
                    hash += column.getIntValue();
                    break;
                case FLOAT:
                    hash += column.getFloatValue().hashCode();
                    break;
            }
        }
    }
    return hash;
}

