    // Check if the graph is empty
    if (vertices.isEmpty()) {
        throw new RuntimeException("cannot provide next vertex: graph is empty");
    }

    // Increment the next vertex counter and wrap around if necessary
    nextVertex++;
    if (nextVertex >= vertices.size()) {
        nextVertex = 0;
    }

    // Return the next vertex
    return vertices.get(nextVertex);
}

