    if (node == null) {
        return false;
    }

    if (node.equals(head)) {
        head = head.next;
    }

    if (node.equals(tail)) {
        tail = tail.prev;
    }

    node.prev.next = node.next;
    node.next.prev = node.prev;

    node.next = null;
    node.prev = null;

    return true;
}

private boolean unlink(ListNodeImpl<E> node){
    // Check if the node is null
    if (node == null) {
        throw new IllegalArgumentException("Invalid node.");
    }

    // Check if the node is the head of the list
    if (node == head) {
        head = node.next;
    }
    else {
        // Find the previous node
        ListNodeImpl<E> prev = head;
        while (prev.next != node) {
            prev = prev.next;
        }

        // Unlink the node
        prev.next = node.next;
    }

    size--;
    return true;
}

public boolean unlink(ListNodeImpl<E> node) {
    // Iterate through the list, checking for a match with the node to be removed
    ListNodeImpl<E> current = head;
    while (current != null) {
        // If we find a match, set the previous node's next pointer to the current node's next pointer
        if (current == node) {
            if (current.prev != null) {
                current.prev.next = current.next;
            }
            return true;
        }
        // If we reach the end of the list without finding a match, return false
        current = current.next;
    }
    return false;
}

private boolean unlink(ListNodeImpl<E> node) {
    // Step 1: Check if the node is null or if it is already removed
    if (node == null || node.getPrevious() == null) {
        return false;
    }

    // Step 2: Get the previous node and the next node
    ListNodeImpl<E> previous = node.getPrevious();
    ListNodeImpl<E> next = node.getNext();

    // Step 3: Update the previous node's next pointer to skip the node
    previous.setNext(next);

    // Step 4: Update the next node's previous pointer to point to the previous node
    next.setPrevious(previous);

    // Step 5: Remove the node's references to the list
    node.setPrevious(null);
    node.setNext(null);

    // Step 6: Return true to indicate that the node was removed
    return true;
}

public boolean unlink(ListNodeImpl<E> node) {
    // Step 1: Check if the node is null
    if (node == null) {
        return false;
    }

    // Step 2: Check if the node is the head of the list
    if (node == head) {
        head = node.next;
        return true;
    }

    // Step 3: Check if the node is the tail of the list
    if (node.next == null) {
        tail = node;
        return true;
    }

    // Step 4: Unlink the node from the list
    node.previous.next = node.next;
    node.next.previous = node.previous;

    // Step 5: Return true if the node was successfully unlinked
    return true;
}

