private String parseToken(final char[] terminators) {
    // Initialize the token buffer and current character index
    StringBuffer tokenBuffer = new StringBuffer();
    int i = 0;

    // While the current character is not a terminator and the end of the input has not been reached
    while (i < input.length() && !Arrays.binarySearch(terminators, input.charAt(i)) >= 0) {
        // If the current character is a letter or digit, add it to the token buffer
        if (Character.isLetterOrDigit(input.charAt(i))) {
            tokenBuffer.append(input.charAt(i));
        }
        i++;
    }

    // If the token buffer is empty, throw an exception
    if (tokenBuffer.length() == 0) {
        throw new IllegalArgumentException("No token found in input");
    }

    // Return the token
    return tokenBuffer.toString();
