public static Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSumList = new ArrayList<>();
    long sum = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSumList.add((int) sum);
    }
    return new Pair<>(suffixSumList, sum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Check if the input list is empty
    if (bounds.isEmpty()) {
        throw new IllegalArgumentException("Input list cannot be empty");
    }

    // Create a new list to store the suffix sum
    List<Integer> suffixSum = new ArrayList<>();

    // Initialize the sum of all elements
    long totalSum = 0L;

    // Iterate through the list in reverse order
    for (int i = bounds.size() - 1; i >= 0; i--) {
        // Get the current element and its index
        int element = bounds.get(i);
        int index = i;

        // Calculate the suffix sum for the current element
        int suffixSumElement = element;
        for (int j = index - 1; j >= 0; j--) {
            suffixSumElement += bounds.get(j);
        }

        // Add the suffix sum to the list and the total sum
        suffixSum.add(suffixSumElement);
        totalSum += suffixSumElement;
    }

    // Return the computed suffix sum list and total sum
    return new Pair<>(suffixSum, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // validate input
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Bounds list cannot be null or empty");
    }

    // initialize output variables
    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;

    // iterate over bounds list and compute suffix sum
    for (int i = bounds.size() - 1; i >= 0; i--) {
        totalSum += bounds.get(i);
        suffixSum.add(0, totalSum);
    }

    return new Pair<>(suffixSum, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Bounds list must not be null or empty");
    }

    // Initialize the suffix sum list
    List<Integer> suffixSum = new ArrayList<>(bounds.size());
    // Initialize the sum of all elements
    long totalSum = 0L;

    // Iterate over the list in reverse order
    for (int i = bounds.size() - 1; i >= 0; i--) {
        // Get the current element
        int element = bounds.get(i);

        // Compute the suffix sum
        suffixSum.add(0, element + (i > 0 ? suffixSum.get(0) : 0));

        // Update the total sum
        totalSum += element;
    }

    // Return the computed suffix sum and the total sum
    return new Pair<>(suffixSum, totalSum);
}

public Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;

    // Edge case: empty list
    if (bounds.isEmpty()) {
        return new Pair<>(suffixSum, totalSum);
    }

    // Handle the base case (last element)
    suffixSum.add(bounds.get(bounds.size() - 1));
    totalSum += bounds.get(bounds.size() - 1);

    // Handle the recursive case
    for (int i = bounds.size() - 2; i >= 0; i--) {
        suffixSum.add(suffixSum.get(i) + bounds.get(i));
        totalSum += suffixSum.get(i) + bounds.get(i);
    }

    return new Pair<>(suffixSum, totalSum);
}

