public void putAllWriteable(BeanMap map) {
    if (map == null) {
        return;
    }

    List<String> readableProperties = new ArrayList<>();
    List<String> writeableProperties = new ArrayList<>();
    List<String> exceptions = new ArrayList<>();

    for (String property : map.keySet()) {
        if (map.isReadable(property)) {
            readableProperties.add(property);
        } else if (map.isWriteable(property)) {
            writeableProperties.add(property);
        } else {
            exceptions.add(property);
        }
    }

    for (String property : readableProperties) {
        put(property, map.get(property));
    }

    for (String property : writeableProperties) {
        setValue(property, map.get(property));
    }

    if (!exceptions.isEmpty()) {
        throw new IllegalArgumentException("The following properties are not valid: " + exceptions.toString());
    }
}

private void put(String property, Object value) {
    if (value == null) {
        throw new IllegalArgumentException("Value cannot be null for property: " + property);
    }
    setter(property).accept(value);
}

private void setValue(String property, Object value) {
    setter(property).accept(value);
}

private Consumer<Object> setter(String property) {
    try {
        return (Consumer<Object>) ((BeanMap) this).getProperty(property).getWriteMethod().invoke(new Object[]{this});
    } catch (ReflectiveOperationException e) {
        throw new IllegalStateException("Unable to find setter for property: " + property);
    }
}

