private List<Pair<List<Pair<Integer,Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer,Integer>>, E>> globalSeparatorList = new ArrayList<>();

    for (E edge : graph.getEdgeList()) {
        List<Pair<Integer, Integer>> minimalSeparators = new ArrayList<>();

        for (V vertex : graph.getVertexList()) {
            if (graph.containsEdge(vertex, edge.getNeighbor(vertex))) {
                minimalSeparators.add(new Pair<>(vertex, edge.getNeighbor(vertex)));
            }
        }

        globalSeparatorList.add(new Pair<>(minimalSeparators, edge));
    }

    return globalSeparatorList;
}

