    List<Pair<List<Pair<Integer, Integer>>, E>> separatorList = new ArrayList<>();
    for (E e : graph.edgeIterable()) {
        List<Pair<Integer, Integer>> minimalSeparatorsInNeighborhood = new ArrayList<>();
        for (V v : graph.vertexIterable()) {
            if (graph.containsEdge(e, v)) {
                List<Pair<Integer, Integer>> separatorsInNeighborhood = computeSeparatorList(v);
                minimalSeparatorsInNeighborhood.addAll(separatorsInNeighborhood);
            }
        }
        separatorList.add(new Pair<>(minimalSeparatorsInNeighborhood, e));
    }
    return separatorList;
}

