public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Check if the name is null or empty
    if (nameStart == null || buf == null) {
        return;
    }

    // Get the length of the name
    int nameLength = buf.length();

    // Check if the name is already short enough
    if (nameLength <= 3) {
        // Just return the original name
        return;
    }

    // Get the first letter of the name
    char firstLetter = buf.charAt(nameStart);

    // Check if the first letter is a vowel
    boolean isFirstLetterVowel = firstLetter == 'a' || firstLetter == 'e' || firstLetter == 'i' || firstLetter == 'o' || firstLetter == 'u';

    // Check if the name starts with a vowel
    boolean startsWithVowel = firstLetter == 'a' || firstLetter == 'e' || firstLetter == 'i' || firstLetter == 'o' || firstLetter == 'u';

    // Abbreviate the name
    if (isFirstLetterVowel && !startsWithVowel) {
        // If the first letter is a vowel and the name doesn't start with a vowel,
        // remove the first letter and append "es"
        buf.deleteCharAt(nameStart);
        buf.append("es");
    } else {
        // If the first letter is not a vowel or the name starts with a vowel,
        // remove the first letter and append "ian"
        buf.deleteCharAt(nameStart);
        buf.append("ian");
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
