        throw new IllegalArgumentException("Invalid name start index");
    }

    if (buf == null) {
        throw new NullPointerException("buf cannot be null");
    }

    int nameEnd = buf.length() - 1;
    while (nameEnd >= nameStart) {
        char c = buf.charAt(nameEnd);
        if (!Character.isLetter(c)) {
            nameEnd--;
        } else {
            break;
        }
    }

    for (int i = nameStart; i <= nameEnd; i++) {
        buf.setCharAt(i, (char) (buf.charAt(i) - 1));
    }
}

