    // If the bound is a class, return it directly
    if (bound instanceof Class) {
        return (Class<?>) bound;
    }

    // If the bound is a parameterized type, get the raw type
    if (bound instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) bound).getRawType();
    }

    // If the bound is a generic array type, get the raw component type
    if (bound instanceof GenericArrayType) {
        return (Class<?>) ((GenericArrayType) bound).getGenericComponentType();
    }

    // Unknown bound type, return Unknown.class
    return Unknown.class;
}

