private static <V, E> boolean exploredVertices(Graph<V, E> graph, V[] vertices) {
    HashSet<V> visited = new HashSet<>();
    for (V vertex : vertices) {
        if (!visited.contains(vertex)) {
            dfsVisit(graph, vertex, visited);
        }
    }
    return visited.containsAll(vertices);
}

private static <V, E> void dfsVisit(Graph<V, E> graph, V vertex, HashSet<V> visited) {
    visited.add(vertex);
    for (E edge : graph.edgesOf(vertex)) {
        V neighbor = graph.getOppositeVertex(vertex, edge);
        if (!visited.contains(neighbor)) {
            dfsVisit(graph, neighbor, visited);
        }
    }
}

