    for (V vertex : vertices) {
        neighbors.addAll(graph.getNeighbors(vertex));
    }

    for (V vertex : vertices) {
        if (!neighbors.containsAll(graph.getNeighbors(vertex))) {
            return false;
        }
    }

    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the given vertices form a complete subgraph
    Set<V> completeVertices = new HashSet<>(vertices);
    Set<E> edges = new HashSet<>(graph.edgeSet());
    for (E edge : edges) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (!vertices.contains(source) || !vertices.contains(target)) {
            return false;
        }
    }
    // Check if the complete subgraph is a clique
    Set<V> neighbors = new HashSet<>();
    for (V vertex : completeVertices) {
        neighbors.addAll(graph.neighborSetOf(vertex));
    }
    return isClique(neighbors);
}

