        if (s.charAt(i) == '{') {
            encodedString += "%7B";
        }
        // If the current character is a right curly brace, encode it as "%7D"
        else if (s.charAt(i) == '}') {
            encodedString += "%7D";
        }
        // If the current character is not a left curly brace or right curly brace, add it to the encoded string as is
        else {
            encodedString += s.charAt(i);
        }
    }

    // Return the encoded string
    return encodedString;
}

