    // Check if the input array is null
    if (array == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }

    // Create a new array to store the non-null elements
    String[] result = new String[array.length];

    // Iterate over the input array and copy non-null elements to the result array
    int count = 0;
    for (int i = 0; i < array.length; i++) {
        if (array[i] == null) {
            continue;
        }
        result[count] = (String) array[i];
        count++;
    }

    // If the result array has fewer elements than the original array, return a new array with the non-null elements
    if (count < array.length) {
        String[] newResult = new String[count];
        System.arraycopy(result, 0, newResult, 0, count);
        return newResult;
    }

    // Otherwise, return the original array
    return array;
}

