    int lastSeparator = indexOfLastSeparator(filename);
    if (lastSeparator == -1) {
        return -1;
    }

    // Check that there is no directory separator after the last dot
    int lastDot = filename.lastIndexOf('.', lastSeparator);
    if (lastDot == -1 || lastDot > lastSeparator) {
