        return Edge(this.nextNode.getRealNode(), this.nextNode.getRealNode());
    }

    return Edge(this.nextNode, this.nextNode);
}

public Edge edgeToNext() {
    // Check if either node is virtual
    if (currentNode.isVirtual()) {
        // Get the real counterpart of the current node
        Node realCurrentNode = currentNode.getRealCounterpart();
        // Get the real counterpart of the next node
        Node realNextNode = nextNode.getRealCounterpart();
        // Return the edge from the real current node to the real next node
        return realCurrentNode.edgeTo(realNextNode);
    } else {
        // Return the edge from the current node to the next node
        return currentNode.edgeTo(nextNode);
    }
}

public Edge edgeToNext() throws InvalidNodeException {
    // Check if the current node is a virtual node and if its real counterpart has been created
    if (isVirtual() && !getRealCounterpart().isCreated()) {
        throw new InvalidNodeException("Cannot create an edge to a virtual node that has not been assigned a real counterpart");
    }

    // Check if the next node is a virtual node and if its real counterpart has been created
    if (getNextNode().isVirtual() && !getNextNode().getRealCounterpart().isCreated()) {
        throw new InvalidNodeException("Cannot create an edge to a virtual node that has not been assigned a real counterpart");
    }

    // Create the edge from the current node to the next node
    Edge edge = new Edge(this, getNextNode());

    // If the current node is a virtual node, add the edge to the real counterpart of the node
    if (isVirtual()) {
        getRealCounterpart().addEdge(edge);
    }

    // If the next node is a virtual node, add the edge to the real counterpart of the node
    if (getNextNode().isVirtual()) {
        getNextNode().getRealCounterpart().addEdge(edge);
    }

    return edge;
}

public Edge edgeToNext() {
    // Check if either of the nodes is virtual
    if (currentNode instanceof VirtualNode) {
        VirtualNode currentVirtualNode = (VirtualNode) currentNode;
        Node realNode = currentVirtualNode.getRealNode();
        // If the current node is virtual, connect it to the real node
        if (realNode != null) {
            return new Edge(realNode, nextNode);
        }
    } else if (nextNode instanceof VirtualNode) {
        VirtualNode nextVirtualNode = (VirtualNode) nextNode;
        Node realNode = nextVirtualNode.getRealNode();
        // If the next node is virtual, connect it to the real node
        if (realNode != null) {
            return new Edge(currentNode, realNode);
        }
    }

    // If neither node is virtual, create a direct edge between them
    return new Edge(currentNode, nextNode);
}

public Edge edgeToNext() {

    // If either of the nodes is virtual, find the real counterpart
    if (currentNode.isVirtual() || nextNode.isVirtual()) {
        currentNode = findRealCounterpart(currentNode);
        nextNode = findRealCounterpart(nextNode);
    }

    // Connect the two nodes with an edge
    Edge edge = new Edge(currentNode, nextNode);
    currentNode.addEdge(edge);

    // Update the current node to the next node
    currentNode = nextNode;

    return edge;
}

Node findRealCounterpart(Node node) {
    // Iterate over all incident edges of the virtual node
    for (Edge edge : node.incidentEdges()) {
        // If the edge is incident to the current node, ignore it
        if (edge.node1 == node) {
            continue;
        }

        // Otherwise, the edge is incident to the real counterpart, so return it
        return edge.node1;
    }

    // If we reach this point, there is no incident edge to the real counterpart,
    // so the virtual node cannot be found
    throw new IllegalStateException("Could not find real counterpart of virtual node " + node);
}

