public int readTag() throws IOException {
    int tag = 0;
    int firstByte;

    // Check if we have reached EOF
    if ((firstByte = is.read()) == -1) {
        return 0;
    }

    // Check if the first byte is a valid start of a tag
    if (firstByte != '0' && firstByte != '1' && firstByte != '2') {
        throw new IOException("Invalid start of tag: " + firstByte);
    }

    // Read the remaining bytes of the tag
    tag = (firstByte - '0') * 10;
    for (int i = 0; i < 3; i++) {
        int nextByte = is.read();
        if (nextByte < '0' || nextByte > '9') {
            throw new IOException("Invalid byte in tag: " + nextByte);
        }
        tag += (nextByte - '0');
    }

    return tag;
}

