String buildContentRange(){
  if (start == null || end == null || total == null) {
    throw new IllegalArgumentException("start, end, and total must be provided");
  }
  if (start < 0 || end < 0 || total < 0) {
    throw new IllegalArgumentException("start, end, and total must be non-negative");
  }
  if (start > end) {
    throw new IllegalArgumentException("start must be less than or equal to end");
  }
  if (start > total || end > total) {
    throw new IllegalArgumentException("end must be less than or equal to total");
  }
  return "bytes " + start + "-" + end + "/" + total;
}

public String buildContentRange() {
    // Check if the file is open
    if (file == null) {
        throw new IllegalStateException("File must be open to build content range");
    }

    // Calculate the content range
    int start = (int) file.getOffset();
    int end = (int) (start + file.getLength() - 1);
    String range = String.format("bytes %d-%d/%d", start, end, file.getLength());

    // Return the content range
    return range;
}

