    // Determine the length of the content
    int contentLength = 0;
    if (this.content != null) {
        contentLength = this.content.length();
    }

    // Determine the range of the content
    int start = 0;
    int end = contentLength - 1;

    // Build the 'Content-Range' header value
    String contentRangeValue = "Content-Range: bytes " + start + "-" + end + "/" + contentLength;

    return contentRangeValue;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    // Check if the file exists
    if (!file.exists()) {
        throw new FileNotFoundException("File not found: " + file.getName());
    }

    // Read the file line by line
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            // Skip any empty or comment lines
            if (line.trim().isEmpty() || line.startsWith("#")) {
                continue;
            }

            // Split the line by comma and trim the elements
            String[] elements = line.split(",");
            for (String element : elements) {
                element = element.trim();

                // Check if the element is a time range, if yes, add it to the timeRanges list
                if (element.startsWith("[")) {
                    element = element.substring(1, element.length() - 1);
                    timeRanges.add(ProfileAnalyzeTimeRange.parse(element));
                } else {
                    // Otherwise, add it to the threadSnapshots list
                    ThreadSnapshot ts = ThreadSnapshot.parse(element);
                    threadSnapshots.add(ts);
                }
            }
        }
    }

    // Filter the threadSnapshots list to contain only the ones within the given time ranges
    for (ThreadSnapshot ts : threadSnapshots) {
        for (ProfileAnalyzeTimeRange tr : timeRanges) {
            if (tr.contains(ts)) {
                if (threadSnapshots.contains(ts)) {
                    threadSnapshots.remove(ts);
                }
                threadSnapshots.add(ts);
            }
        }
    }

    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    BufferedReader reader = new BufferedReader(new FileReader(file));
    String line;
    while ((line = reader.readLine()) != null) {
        if (line.startsWith("THREAD_SNAPSHOT:")) {
            String[] tokens = line.substring(13).split("[ |=|;|;]");
            long threadId = Long.parseLong(tokens[0]);
            long timestamp = Long.parseLong(tokens[1]);
            String detail = tokens[2];
            ThreadSnapshot snapshot = new ThreadSnapshot(threadId, timestamp, detail);
            snapshots.add(snapshot);
        }
    }
    reader.close();
    return snapshots;
}

