        while ((line = reader.readLine()) != null) {
            if (line.startsWith("thread_id")) {
                continue;
            }
            String[] args = line.split(" ");
            if (args.length < 3) {
                throw new IOException("Invalid snapshot record");
            }
            int threadId = Integer.parseInt(args[0]);
            long startTime = Long.parseLong(args[1]);
            long endTime = Long.parseLong(args[2]);
            ProfileAnalyzeTimeRange timeRange = timeRanges.get(threadId);
            if (timeRange == null) {
                continue;
            }
            if (startTime >= timeRange.getStartTime() && startTime < timeRange.getEndTime() ||
                endTime >= timeRange.getStartTime() && endTime < timeRange.getEndTime()) {
                threadSnapshots.add(new ThreadSnapshot(threadId, startTime, endTime));
            }
        }
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] values = line.split(",");
            long timestamp = Long.parseLong(values[0]);
            double threadId = Double.parseDouble(values[1]);
            String stackTrace = values[2];

            // Check if the timestamp is within the time range
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
                    threadSnapshots.add(new ThreadSnapshot(timestamp, threadId, stackTrace));
                    break;
                }
            }
        }
    }

    return threadSnapshots;
}

public static List<ThreadSnapshot> loadThreadSnapshotsWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

  List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

  InputStream inputStream = new FileInputStream(file);

  try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {

    String line;
    while ((line = reader.readLine()) != null) {

      try {
        ThreadSnapshot threadSnapshot = ThreadSnapshot.from(line);
        ProfileAnalyzeTimeRange timeRange = ProfileAnalyzeTimeRange.fromInterval(threadSnapshot.getStartTime(), threadSnapshot.getEndTime());

        if (timeRanges.contains(timeRange)) {
          threadSnapshots.add(threadSnapshot);
        }
      } catch (Exception e) {
        e.printStackTrace();
      }
    }
  }

  return threadSnapshots;
}
